export default scene({mode:'2d',end:'hold',audio:'narration-0',background:'BLACK'},s=>{
    const duration=7.455291666666667;let elapsed=0;
    const wait=t=>{s.wait(t);elapsed+=t;};const play=(a,t)=>{s.play(a,{duration:t,ease:'linear'});elapsed+=t;};
    const label=(id,lines,x,y,size,fill)=>lines.forEach((text,i)=>s.text(id+'-'+i,{text,position:[x,y-i*size*1.4],fontSize:size,fill}));
    s.play(s.camera.to2D({height:8}),{duration:0});
    label('scene',['Szene 1 / 4'],0,3.7,.18,'GREY_B');
    label('title',["Warum erfindet eine KI Angaben?"],0,3.18,.31,'WHITE');

        label('prompt',['Das Team trifft sich nächsten …'],0,1.8,.32,'WHITE');
        const words=['Montag','Dienstag','Mittwoch','Freitag','Juni'], values=[1,.46,.37,.22,.13];
        words.forEach((word,i)=>{
          const y=.9-i*.7;
          label('word-'+i,[word],-3.8,y,.27,i===0&&false?'YELLOW':'WHITE');
          const bar=s.line('bar-'+i,{points:[[-2.2,y],[-2.2+6*values[i],y]],stroke:i===0&&false?'YELLOW':'BLUE',strokeWidth:.25,opacity:0});
          play(bar.fadeIn(),Math.min(.25,duration/10));
        });
        label('example',['Beispielwerte: sprachlich passend ist nicht automatisch wahr.'],0,-3,.2,'GREY_B');
    wait(Math.max(0,duration-elapsed));
  });

